(function () {
  const root = document.querySelector('[data-apiease-discount-code-lookup]');
  if (!root) return;

  const form = root.querySelector('[data-role="form"]');
  const input = root.querySelector('[data-role="code-input"]');
  const button = root.querySelector('[data-role="submit-button"]');
  const status = root.querySelector('[data-role="status"]');
  const result = root.querySelector('[data-role="result"]');
  const requestId = root.getAttribute('data-request-id') || 'lookup-shopify-discount-code-details';

  function setStatus(message, state) {
    status.textContent = message || '';
    status.setAttribute('data-state', state || '');
  }

  function setLoading(isLoading) {
    input.disabled = isLoading;
    button.disabled = isLoading;
    button.textContent = isLoading ? 'Looking up...' : 'Lookup Discount';
  }

  function clearResult() {
    result.replaceChildren();
  }

  function appendRow(list, label, value) {
    const term = document.createElement('dt');
    term.textContent = label;
    const description = document.createElement('dd');
    description.textContent = value == null || value === '' ? 'None' : String(value);
    list.append(term, description);
  }

  function formatDate(value) {
    if (!value) return 'None';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return value;
    return date.toLocaleString();
  }

  function normalizePayload(jsonResponse) {
    const data = jsonResponse && Object.prototype.hasOwnProperty.call(jsonResponse, 'data')
      ? jsonResponse.data
      : jsonResponse;

    if (typeof data === 'string') {
      try {
        return JSON.parse(data);
      } catch (error) {
        return { ok: false, message: 'Unable to parse APIEase response.' };
      }
    }

    return data || { ok: false, message: 'No response was returned.' };
  }

  function appendItems(container, title, items) {
    if (!Array.isArray(items) || items.length === 0) return;

    const heading = document.createElement('h3');
    heading.textContent = title;
    const list = document.createElement('ul');

    items.forEach(function (item) {
      const listItem = document.createElement('li');
      if (item.url) {
        const link = document.createElement('a');
        link.href = item.url;
        link.textContent = item.title || item.handle || item.id;
        listItem.append(link);
      } else {
        listItem.textContent = item.title || item.handle || item.id;
      }
      list.append(listItem);
    });

    container.append(heading, list);
  }

  function appendRawDetails(container, detailsPayload) {
    if (!detailsPayload || typeof detailsPayload !== 'object') return;

    const details = document.createElement('details');
    const summary = document.createElement('summary');
    const pre = document.createElement('pre');

    summary.textContent = 'Raw discount details';
    pre.textContent = JSON.stringify(detailsPayload, null, 2);
    details.append(summary, pre);
    container.append(details);
  }

  function renderPayload(payload) {
    clearResult();

    if (!payload.ok) {
      setStatus(payload.message || 'Unable to lookup discount code.', 'error');
      return;
    }

    if (!payload.found) {
      setStatus(payload.message || 'No discount code was found.', 'error');
      return;
    }

    setStatus('Discount code found.', 'success');

    const panel = document.createElement('div');
    panel.className = 'apiease-discount-lookup__panel';
    const list = document.createElement('dl');

    appendRow(list, 'Discount code', payload.code);
    appendRow(list, 'Discount title', payload.title);
    appendRow(list, 'Status', payload.status);
    appendRow(list, 'Discount type', payload.type);
    appendRow(list, 'Starts at', formatDate(payload.startsAt));
    appendRow(list, 'Ends at', formatDate(payload.endsAt));
    appendRow(list, 'Usage count', payload.usageCount);
    appendRow(list, 'Usage limit', payload.usageLimit);
    appendRow(list, 'Value', payload.valueSummary);
    appendRow(list, 'Minimum requirement', payload.minimumRequirement);
    appendRow(list, 'Applies to all items', payload.appliesToAllItems ? 'Yes' : 'No');

    panel.append(list);
    appendItems(panel, 'Eligible products', payload.eligibleProducts);
    appendItems(panel, 'Eligible collections', payload.eligibleCollections);
    appendRawDetails(panel, payload.details);
    result.append(panel);
  }

  form.addEventListener('submit', async function (event) {
    event.preventDefault();

    const code = input.value.trim();
    clearResult();

    if (!code) {
      setStatus('Enter a discount code.', 'error');
      input.focus();
      return;
    }

    setLoading(true);
    setStatus('Looking up discount code...', '');

    try {
      const response = await apiease.runRequest(requestId, {
        liquidParamsEmbedded: { code: code }
      });

      if (response.status < 200 || response.status >= 300) {
        setStatus(
          response.errorMessage || 'Unable to lookup discount code.',
          'error'
        );
        return;
      }

      renderPayload(normalizePayload(response));
    } catch (error) {
      setStatus(
        error.message || 'Unable to lookup discount code.',
        'error'
      );
    } finally {
      setLoading(false);
    }
  });

})();
